def validation_diagnostic(error):
    reason = error.args[0] if type(error) in {ResearchError, ContractError} and len(error.args) == 1 and type(error.args[0]) is str else None
    code, path, action = _REASONS.get(reason, (
        "artifact_validation_failed", "artifact", "Revise a estrutura e as evidências do resultado; nenhuma nova tentativa será automática."))
    return {"code": code, "path": path, "action": action}
